System.Collections.IEnumerator Run(){
 var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
 var rb=rig.body.GetComponent<UnityEngine.Rigidbody2D>();rb.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
 var start=rig.tip.position; float max=0;string log="";
 for(int i=0;i<120;i++){
  float angle=i*UnityEngine.Mathf.PI*2/120;
  var world=rig.body.position+new UnityEngine.Vector3(UnityEngine.Mathf.Cos(angle),UnityEngine.Mathf.Sin(angle),0)*1.65f;
  var screen=UnityEngine.Camera.main.WorldToScreenPoint(world);
  UnityEngine.InputSystem.InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,new UnityEngine.InputSystem.LowLevel.MouseState{position=new UnityEngine.Vector2(screen.x,screen.y)});
  yield return new UnityEngine.WaitForFixedUpdate();yield return null;
  max=UnityEngine.Mathf.Max(max,rig.HandError);
 }
 log="Mouse input event -> TargetMovement -> actual physical paddle motion="+UnityEngine.Vector3.Distance(start,rig.tip.position)+"; max grip error="+max+"; dead="+rig.body.GetComponent<Character.Lifecycle.Death>().Dead;
 System.IO.File.WriteAllText("scripts/player-art-20261111/input.txt",log);UnityEngine.Debug.Log(log);
}
return Run();
